// ЗГЕНЕРОВАНО scripts/import-kb.mjs з content/kb-source/ за content/kb-include.json. Не редагувати вручну.
const data: unknown = {"ECO-01":{"title":"Умови офера","body":"Перед тестом запиши оплачувану дію, ставку й валюту, географію, дозволені джерела, ліміт і часовий пояс. Уточни вікно атрибуції, правила щодо дублів, причини відхилення, холд і порядок виплат. Збережи дату й версію умов. Кап 50 без назви події неоднозначний: це можуть бути заявки, підтвердження або продажі."},"ECO-02":{"title":"Граничний CPL","body":"Якщо платять за підтвердження, виплата $25 і підсумковий апрув 40% від усіх заявок дають $10 очікуваного доходу на заявку. За $2 інших змінних витрат на заявку граничний рекламний CPL становить $8. Формула: виплата × частка оплачуваних заявок − інші змінні витрати на заявку. Не множ на частку викупу, якщо оплата залежить лише від підтвердження."},"ECO-03":{"title":"Два знаменники апруву","body":"Зі 100 заявок 80 валідні, 32 підтверджені. Апрув від усіх заявок — 32%, від валідних — 40%. Для оцінки доходу на кожну залучену заявку використовуй 32%; 40% допомагають аналізувати роботу з валідними заявками. Порівнюючи звіти, зазначай знаменник і дату зрізу."},"ECO-04":{"title":"Незавершена когорта","body":"Із 20 заявок 4 підтверджені, 8 відхилені й 8 очікують рішення. Спостережуваний апрув від усіх — 20%; серед уже опрацьованих — 33,3%. Якщо закриті статуси остаточні, можливий підсумковий апрув зараз становить від 20% до 60%. Порівнюй когорти однакового віку й зазначай затримку обробки."},"ECO-05":{"title":"Діагностика якості лідів","body":"Почни з розподілу причин за однаковим віком заявок, креативом, сторінкою, регіоном і часом. Дублі й помилки форми вказують на одні гіпотези; недодзвін, затримка обробки та відмова через ціну — на інші. Запитай визначення кожного статусу й час до першого контакту. Змінюй по одному чиннику, щоб можна було інтерпретувати наступний тест."},"ECO-06":{"title":"Порівняння двох оферів","body":"За виплати $30 й апруву 25% очікуваний дохід на заявку — $7,50. За виплати $20 й апруву 45% — $9. Це оцінка для зіставних зрілих когорт і однакового визначення апруву. Порівняй також рекламний CPL, повернення й строки виплати. EPC партнерської мережі стосується її вибірки й може відрізнятися від твого."},"ECO-07":{"title":"Прибуток і обігові кошти","body":"Витрати становили $400 на рекламу й $50 на інші змінні витрати. Підтверджена виручка $540 дає прибуток за врахованими витратами $90 і ROI 20%. Якщо виручка ще на холді, для наступного запуску потрібні доступні кошти. Веди окремо нараховане, доступне до виведення й фактично отримане."},"ECO-08":{"title":"Бюджет і умова зупинки тесту","body":"До запуску запиши питання тесту, допустимий збиток, метрику для рішення й строк дозрівання статусів. Правило «витратити три виплати» — евристика окремого автора. За однакової виплати й різних CPL, апруву та строків обробки однаковий бюджет дасть різну кількість корисних спостережень. Перед масштабуванням перевір, чи достатньо даних для рішення."},"ECO-09":{"title":"Аудит опублікованого кейсу","body":"У навчальному прикладі автор зазначив дохід $2 400, рекламні витрати $1 500, прибуток $950 і ROI 63%. Прямий перерахунок за опублікованими рядками дає $900 і 60%. Спочатку запитай про пропущені статті та правила округлення. Для порівняння також потрібні період кампанії, зрілість заявок, валюти й охоплення витрат."},"ECO-10":{"title":"Звірка статусів між системами","body":"Для однієї когорти зафіксуй період, часовий пояс, визначення конверсії та дату вивантаження. Зістав записи за дозволеним ідентифікатором події або заявки. Окремо познач відсутні події, повторні записи та зміну статусу. Спочатку визнач точку розбіжності, потім перевіряй гіпотезу про якість трафіку."},"EXP-01":{"title":"Гіпотеза перед запуском","body":"Запиши варіант, очікуваний ефект, механізм, основну метрику й умову рішення. Наприклад, демонстрація збирання збільшить частку оплачуваних замовлень, бо зніме питання про складність. До запуску визнач контроль, бюджет, вікно дозрівання й допустимі втрати."},"EXP-02":{"title":"Модульний бриф креативу","body":"Фіксуй аудиторію, задачу, обіцянку, доказ і дію. Розклади креатив на перший кадр, демонстрацію, аргумент і CTA. Для перевірки першого кадру збережи решту елементів і дай версіям ID. Якщо змінюєш усю концепцію, оцінюй її в цілому."},"EXP-03":{"title":"Узгодженість оголошення й сторінки","body":"Перевір, чи узгоджені товар, ціна, умови доставки, оплата й обіцяний результат на всіх кроках. На першому екрані відвідувач має зрозуміти, куди потрапив, що отримає та за що платить. Якщо обіцянку неможливо підтвердити, виправ її в оголошенні й на сторінці."},"EXP-04":{"title":"Показники за етапами воронки","body":"CTR = вибрані кліки / покази. CVR сторінки = заявки / вибрані відвідування або кліки. Апрув = підтвердження / заздалегідь визначений набір заявок. Використовуй однакове визначення кліку в обох варіантах. Одна метрика верхнього етапу не описує всю економіку."},"EXP-05":{"title":"Контроль і призначення варіанта","body":"Одночасний запуск двох оголошень сам по собі не означає контрольований спліт. Уточни одиницю розподілу, механізм призначення й можливий перетин аудиторій. Веди журнал змін. Якщо варіанти змінювали в різні дні або за різних умов, висновок про причинність обмежений."},"EXP-06":{"title":"Розподіл і доставка","body":"Заданий розподіл і фактичні покази можуть відрізнятися через аукціон, бюджет або фільтрацію. Перевір очікувану частку в тій одиниці, яку справді призначає експеримент. За значної розбіжності спочатку шукай причину, потім тлумач ефект."},"EXP-07":{"title":"Зупинка, продовження й вибір","body":"До тесту визнач ліміт втрат, строк перевірки, критерій успіху й умови аварійної зупинки. Рання перевага за кількома подіями може змінитися. За малої вибірки або незрілих заявок залишай результат невизначеним, навіть якщо попередня економіка виглядає кращою."},"EXP-08":{"title":"Діагностика падіння результату","body":"Спочатку визнач перший етап, який змінився: ціна показу, кліки, вхід на сторінку, заявки, підтвердження. Звір дати, версію креативу й зріз аудиторії. Зростання частоти разом зі зниженням CTR — привід перевірити втому аудиторії. Сам патерн не встановлює причини."},"FB-01":{"title":"Власник активів і доступ","body":"Перед запуском зістав бізнес-портфель, рекламний акаунт, сторінку й джерело подій. Запиши власника кожного активу, відповідального за оплату й дозволи своєї ролі. Якщо потрібного джерела немає в списку, спочатку перевір акаунт і доступ до активу."},"FB-02":{"title":"Джерело подій і зміст сигналу","body":"Pixel передає події з браузера, а серверна інтеграція може передавати дозволені події окремим шляхом. Визнач, що кожна подія означає у воронці, хто її створює й до якого джерела вона надходить. Назва Purchase не перетворює надсилання форми на покупку."},"FB-03":{"title":"Перевірка контрольної заявки","body":"Проведи одну погоджену тестову заявку через потрібну сторінку. Збережи час, тестовий ID, очікувану назву події та фактичний статус. Перевір джерело подій, журнал доставлення й запис у CRM. Повторне відкриття сторінки саме по собі не має створювати ще одну заявку. Реєстрацію події та атрибуцію у звіті перевіряй окремо."},"FB-04":{"title":"Браузер і сервер в одній перевірці","body":"Якщо обидва канали повідомляють про одну дію, порівняй записи за назвою події та ідентифікатором. Перевір результат дедуплікації в діагностиці джерела. Зберігай один ID для копій однієї дії та різні ID для окремих дій у схемі, яку перевіряєш. Правила конкретної інтеграції слід звіряти перед впровадженням."},"FB-05":{"title":"Перевірка оголошення й обмеження","body":"Розрізняй перевірку оголошення, обмеження акаунта, проблему оплати й відсутність показів. Зафіксуй конкретний статус і причину, потім перевір сторінку, рекламні твердження й правила категорії. Після звірки причин скористайся штатним виправленням або запитом на перегляд. Знімок зі старої інструкції не підтверджує, що дія доступна зараз."},"FB-06":{"title":"Що змінювати в перші дні","body":"Спочатку перевір покази, роботу події та зрілість заявок. Виправлення явної поломки зафіксуй окремим записом у журналі. Для оптимізації запиши одне запитання й умову наступного рішення. Не виводь універсальну кількість днів, подій чи відсотків збільшення бюджету з окремого кейсу."},"FBR-01":{"title":"Ціль і налаштування показу","body":"Почни з результату бізнесу. Для лідогенерації випиши місце конверсії, доступний сигнал і його зв’язок з оплачуваною дією. Перевір, чи вибрана комбінація доступна саме в цьому акаунті. Якщо сигнал надто рідкісний або ненадійний, оціни якість вимірювання до зміни налаштування."},"FBR-02":{"title":"Бюджет за рівнем і ліміт тесту","body":"Познач, де задано бюджет, період його дії, валюту рахунку й фактичні витрати кожної групи. За спільного бюджету різний показ груп може вплинути на порівняння матеріалів. Для навчального тесту заздалегідь визнач ліміт втрат і критерій зупинки. Поріг із чужого кейсу розглядай лише як гіпотезу."},"FBR-03":{"title":"Від звіту до наступного рішення","body":"Якщо витрат немає, спочатку знайди причину зупинки показу. Якщо витрати є, пройди ланцюжок показ → клік → заявка → зарахування. Зістав дату й вікно атрибуції, курс валюти за потреби та зрілість статусів. У рішенні вкажи перевірку, відповідального й момент наступного перегляду."},"GEO-01":{"title":"Країни, Tier 1/2/3 і рішення щодо запуску","body":"## Як читати тіри\n\nGEO — ринок кампанії: країна або конкретний регіон, який може обслужити рекламодавець. Tier 1/2/3 — умовне групування GEO у маркетингових джерелах. Списки можуть різнитися навіть у двох рекламних мереж. Це швидка підказка для пошуку ринку й побудови гіпотез. Фактична ціна трафіку, доступність реклами та економіка мають перевірятися окремо.\n\n| Країна | ISO | PropellerAds | ROIads |\n|---|---|---|---|\n| США | US | Tier 1 | Tier 1 |\n| Велика Британія | GB | Tier 1 | Tier 1 |\n| Німеччина | DE | Tier 1 | Tier 1 |\n| Україна | UA | Tier 2 | Tier 2 |\n| Бразилія | BR | Tier 2 | Tier 2 |\n| Польща | PL | Tier 2 | Tier 1 |\n| Мексика | MX | Tier 2 | Tier 3 |\n| В’єтнам | VN | Tier 3 | Tier 3 |\n| Нігерія | NG | Tier 3 | Tier 3 |\n\nЦе приклади з конкретних довідників, а не повний список або класифікація Meta. Збіг у двох джерелах не встановлює вартість трафіку в третьому каналі. Публікації про push/pop не використовувати як джерело CPM/CPL для Meta або Google Search. Групи доходу Світового банку — окремий економічний показник, не переклад Tier 1/2/3.\n\nДжерела: [PropellerAds · список GEO](https://propellerads.com/blog/what-is-a-tier-of-traffic-and-what-tier-should-you-choose/) · [ROIads · список GEO](https://roiads.co/blog/tier-1-2-and-3-countries-in-affiliate-marketing-how-to-maximize-profits-across-geos/) · [Світовий банк · групи доходу](https://datahelpdesk.worldbank.org/knowledgebase/articles/906519-world-bank-country-and-lending-groups).\n\n## Профіль GEO для запуску\n\n1. **Ринок і допуск.** Код країни, регіони обслуговування, вертикаль і тип офера, джерело трафіку, вимоги платформи та ринку, джерело й дата перевірки. Якщо потрібний дозвіл не підтверджено, цей запуск не плануємо.\n2. **Офер і локалізація.** Мова оголошення, лендингу та підтримки, ціна і валюта для клієнта, способи оплати, доставка або графік надання послуги. У партнерській моделі додати список GEO, ставку, оплачувану подію, капу, строки й правила відхилення.\n3. **Сетап кампанії й акаунта.** Перевірити правила геотаргетингу, регіони виключення, подію оптимізації, тестову заявку або замовлення. В окремих полях зафіксувати країну рекламодавця/платіжного профілю, дозволений спосіб оплати, валюту рекламного акаунта, часовий пояс звітів і валюту виплати. Використовувати справжні дані бізнесу та офіційні ролі. GEO показу не визначає автоматично країну платіжного профілю. Для Google Ads також відрізняти людей, які перебувають у місці, від тих, хто проявив до нього інтерес.\n4. **Бюджет.** Записати фактичні витрати за період, джерело оцінки CPL/CPA, валюту, обсяг цільових подій, межу збитку й час дозрівання даних. Окремо врахувати витрати поза рекламою та обмін валют. За відсутності локальних цифр дати навчальний розрахунок і явно позначити припущення.\n5. **Порівняння GEO.** Якщо країни мають різну виплату, мову чи спосіб виконання замовлення, відстежувати результат окремо. У навчальному тесті тримати спільні визначення подій і порівнюваний вік когорт. Об’єднувати дані лише тоді, коли це не приховує різну економіку або вимоги.\n\nДжерела: [Google Ads · принципи геотаргетингу](https://support.google.com/google-ads/answer/2453995) · [Meta · бюджет групи оголошень](https://developers.facebook.com/docs/graph-api/reference/ad-campaign/) · [Meta · бізнес-активи, ролі та спосіб оплати](https://developers.facebook.com/docs/business-management-apis/business-asset-management/overview).\n\n## Навчальний приклад бюджету\n\nДва вигадані ринки, одна валюта розрахунку. На ринку А прогнозний CPL — €8, виплата — €30, частка оплачуваних заявок — 40%, інші витрати — €2 на заявку. Граничний CPL становить €10, прогнозний внесок після реклами — €2 на заявку. На ринку Б прогнозний CPL — €4, виплата — €14, оплачувана частка — 35%, інші витрати — €1. Граничний CPL — €3,90, прогнозний результат — −€0,10 на заявку.\n\nЗа умовних 30 заявок медіавитрати становили б €240 та €120. Це арифметичний приклад, не ціна трафіку або вимога до вибірки. Запитання учневі: чому дешевший ринок може не окупитися? Які дані треба підтвердити перед запуском?\n\n## Що перевіряти у восьми вертикалях\n\n| Вертикаль | Що найбільше змінює рішення по GEO |\n|---|---|\n| Товарка | Локальна маржа, способи оплати, доставка, викуп і повернення. |\n| Послуги | Реальна зона обслуговування, доступність команди, час відповіді, вартість виграної угоди. |\n| Інфобіз | Мова продукту, локальна ціна, умови оплати та повернення. |\n| Нутра | Категорія товару і допустимість конкретних тверджень для ринку та каналу. |\n| Дейтинг | Категорія сервісу, допуск платформи, вікові обмеження й приватність. |\n| Гемблінг | Статус оператора, допустимість каналу, вікові вимоги та захист аудиторії. |\n| Крипта | Статус конкретної компанії та послуги, юрисдикція, допустимість просування. |\n| Адалт | Категорія продукту, допуск каналу, вимоги до віку, згоди та приватності. |\n\nКартка не підтверджує допуски для перелічених країн. Для регульованих категорій додавати до профілю GEO посилання на актуальні правила й окремий результат перевірки. Для бюджету зберігати країну, вертикаль, канал, період, витрати, назву події та джерело. Поле Tier зберігати разом із назвою довідника й датою. За розбіжності залишати обидва значення."},"MET-01":{"title":"Три рівні кабінету","body":"Кампанія задає ціль. Група оголошень об’єднує оголошення зі спільними параметрами показу. Оголошення містить креатив і місце призначення. Перед зміною з’ясуй, на якому рівні потрібний параметр. Бюджет може задаватися на різних рівнях залежно від режиму."},"MET-02":{"title":"Ціль, подія й результат бізнесу","body":"Запиши три поля: ціль кампанії, сигнал оптимізації й результат за договором. Надсилання форми може бути сигналом, а оплачуване замовлення — підсумком. Звір назви та джерела подій у кабінеті й системах обліку. Зміна цілі або сигналу змінює запитання тесту."},"MET-03":{"title":"Перевірка перед запуском","body":"У чернетці перевір ринок, місце призначення оголошення, бюджет, розклад і версію креативу. Проведи контрольну заявку й простеж її до першого очікуваного статусу. Зафіксуй, де перевіряти витрати й коли зупинити тест. Зміни інтерфейсу та правила категорії перевіряй окремо."},"MET-04":{"title":"Діагностика відсутності показів","body":"Знайди перший рівень, де зупинився показ. Перевір статус кампанії, групи й оголошення, розклад, обмеження та бюджет. Якщо показів немає, CTR і CVR ще не описують роботу креативу. Запиши фактичну причину й час перевірки до змін."},"MET-05":{"title":"Зріз показників і зміна версії","body":"Вибери рівень звіту, вікно, часовий пояс, цільову дію й версію креативу. Зістав витрати й події за одним зрізом. Якщо змінювалися аудиторія, бюджет і креатив, виділи інтервали до й після та не приписуй увесь ефект одній зміні."},"MET-06":{"title":"Сайт чи форма всередині Facebook","body":"Заявку можна збирати на своїй сторінці або у формі всередині платформи. Шлях людини в цих варіантах різний: у другому вона не переходить на сайт і бачить менше інформації про товар і умови.\n\nГіпотеза для перевірки: кількість заявок і частка оплачуваних можуть змінитися в різні боки.\n\nКоли обираєш «Сайт», кабінет сам показує підказку, що поєднане місце «Сайт і миттєві форми» може знизити ціну за лід на 14–24% (*підказка кабінету Ads Manager, перевірено 16.11.2026*). Це обіцянка щодо ціни заявки, а не щодо оплачуваного результату.\n\nПорівнюй варіанти за оплачуваним результатом, а не за CPL. Зміна місця збору змінює сигнал, шлях і склад заявок, тому це окремий тест."},"MET-07":{"title":"Аудиторія й місця показу на рівні набору реклами","body":"У наборі реклами задається, кому й де показувати: географія, вік, мова, детальні ознаки, місця показу.\n\nГіпотеза для перевірки: ширина аудиторії впливає на ціну і якість заявок, напрям впливу заздалегідь невідомий.\n\nВ одному тесті змінюй одне налаштування. Перед запуском запиши, які налаштування автоматичні, а які задані вручну: назви автоматичних режимів в інтерфейсі змінюються."},"NUT-01":{"title":"Категорія продукту","body":"«Нутра» — робоча назва вертикалі. Для конкретного продукту запиши склад, призначення, форму, ринок і заявлений ефект. Далі перевір застосовну категорію продукту й правила платформи. Назви офера недостатньо, щоб надійно визначити категорію."},"NUT-02":{"title":"Пряма й непряма обіцянка","body":"Перевір не лише заголовок. Візуал, відгук, озвучення, послідовність кадрів і сторінка разом формують очікування. Запиши, якого результату глядач може обґрунтовано очікувати. Для непідтвердженої обіцянки прибери і пряму фразу, і елементи, які створюють те саме очікування."},"NUT-03":{"title":"Перевірка доказу","body":"Рознеси твердження й доказ в окремі поля. Зістав конкретний продукт, склад, умови застосування, аудиторію та виміряний результат. Позитивний відгук або дослідження іншого продукту не підтверджують заявлений ефект. Допустимість формулювання перевіряй для вибраного ринку."},"NUT-04":{"title":"Нутра: якість замовлення й повернення","body":"Зістав рекламу й сторінку з фактичними умовами продажу. Розподіли причини скасування за вартістю, очікуваннями, доставкою й обробкою. Низький CPL може поєднуватися з поганою економікою, якщо частина заявок не стає оплачуваними замовленнями. Рахуй внесок після скасувань за зрілою когортою."},"NUT-05":{"title":"Картка редакторського допуску","body":"Збережи формулювання обіцянки, продукт, ринок, тип доказу, дату перегляду й статус. Окремо перевір допустимість за вимогами ринку та правилами вибраної платформи. Якщо однієї з умов не підтверджено, залиш завдання на перевірку й використай в уроці вигаданий приклад."},"OPS-01":{"title":"Карта інструментів","body":"Рознеси ролі інструментів: кабінет керує закупівлею, трекер пов’язує шлях кліку, CRM веде статус заявки, платіжна система відображає списання й повернення, журнал витрат зберігає витрати. Для кожного рішення вибери відповідальне джерело й спосіб звірити його з іншим."},"OPS-02":{"title":"Оцінювання сервісу до оплати","body":"Опиши задачу, мінімальний набір даних, потрібні ролі, можливість експорту й наслідки зупинки сервісу. Перевір власника, ціну з комісіями, підтримку й перенесення даних. Для мережевих сервісів і проксі оцінюй законну задачу, доступ до даних та якість з’єднання. Перевіряй обмеженим тестом."},"OPS-03":{"title":"Перевірка партнера й договору","body":"Зістав юридичну особу, домен, контакт і отримувача платежу. Уточни оплачувану дію, правила перерахунку, порядок спору й строки виведення. Незалежно перевір несподівану зміну реквізитів через уже відомий канал. Почни з обмеженого обсягу й звір перший розрахунок."},"OPS-04":{"title":"Доступи в команді","body":"Кожен учасник має власний доступ за роллю. Власник фіксує, хто затверджує витрати й хто змінює кампанії. Увімкни багатофакторний захист, переглядай доступ при зміні ролі та закривай його, коли людина йде. Навчальні скриншоти й завдання роби з вигаданими акаунтами."},"OPS-05":{"title":"Журнал рішень і масштабування","body":"Для кожної суттєвої зміни запиши дату, причину, очікуваний ефект, метрику й умову повернення. Перед збільшенням обсягу перевір зрілість результатів, запас бюджету, ліміти офера й здатність обробити заявки. Після зміни порівняй зі зіставним періодом і запиши, що ще невідомо."},"OPS-06":{"title":"Ознаки обману й реакція","body":"Термінова передоплата, обіцянка гарантії, зміна отримувача платежу й прохання передати пароль або код — причини призупинити дію. Зафіксуй запит, перевір його через відомий канал і повідом відповідального. Якщо доступ міг бути розкритий, дій за процедурою організації та збережи журнал інциденту."},"PAY-01":{"title":"Оплачувана дія: CPA, CPL і CPS","body":"CPA означає оплату за узгоджену дію. CPL уточнює, що предмет розрахунку — лід за умовами програми. CPS прив’язаний до продажу. Узгодь точний критерій, строк перевірки й підстави скасування. У звіті познач рекламний CPL окремо від комісії за лід."},"PAY-02":{"title":"База розрахунку RevShare","body":"Частка 25% не пояснює, від якої суми її рахують. Уточни базу: визнана виручка, повернення, комісії та інші відрахування. Порівнюй за одним періодом, валютою й когортою. Перевір, коли частку припиняють нараховувати за договором."},"PAY-03":{"title":"Гібридна модель","body":"Гібрид поєднує фіксовану виплату за дію й частку від визначеної бази. Обчисли кожну частину окремо й порівняй з альтернативою на вибраному горизонті. Перевір винятки, затримки та можливість скасування кожної частини. Майбутні нарахування позначай як прогноз."},"PAY-04":{"title":"Звірка нарахувань і виплат","body":"Для кожної когорти перевір чотири значення: попередньо нараховано, затверджено, доступно до виплати й отримано. Познач окремими рядками скасування, комісію за переказ і валютне коригування. Зберігай ID розрахунку й дату. За розбіжності запитуй правила й деталізацію."},"PAY-05":{"title":"Перевірка допуску за категорією","body":"Для продукту на межі категорій зафіксуй категорію, географію, формат реклами, цільову подію й тип аудиторії. Окремо перевір вимоги платформи, умови програми й застосовні місцеві правила. Сертифікація платформи та ліцензія відповідають на різні запитання. Якщо дозволеність не підтверджена, залиш статус «потребує перевірки»."},"RSK-01":{"title":"Перший і заліковий депозит","body":"FTD зазвичай означає перший депозит. Для зарахування договір може вимагати додаткової перевірки. Рознеси реєстрацію, перший депозит, зарахування, скасування й виплату в різні поля. Запитай підстави відхилення та строк звірки. Депозит гравця сам по собі не дорівнює доходу партнера."},"RSK-02":{"title":"База частки в гемблінгу","body":"Попроси визначити базу RevShare, перелік відрахувань, період і порядок від’ємних коригувань. Не підміняй її сумою депозитів. Порівнюй фіксовану виплату й частку на однаковому горизонті. Збережи розрахунок із розбивкою нарахувань і залишку до виплати."},"RSK-03":{"title":"Оператор, партнер і ринок","body":"До оцінки реклами з’ясуй, хто оператор, хто партнер, хто володіє цільовою сторінкою й де показується реклама. Звір документи окремо для оператора, партнера й платформи. Не перенось допуск однієї юридичної особи чи країни на інший ринок або домен."},"RSK-04":{"title":"Захист аудиторії","body":"Перевір правила щодо віку, вразливих аудиторій і самовиключення там, де воно застосовне. Відсутність попередження в кабінеті не підтверджує допуск. Перевір прозорість умов в оголошеннях і на сторінці. Для навчальної аналітики використовуй вигадані записи."},"RSK-05":{"title":"Категорія криптопродукту","body":"Розрізняй навчання, гаманець, обмін, інвестиційну пропозицію та власне приймання оплати в криптовалюті. Перед оцінкою офера опиши функцію, власника продукту й рух коштів. Перевір правила для потрібної категорії, ринку та рекламної платформи."},"RSK-06":{"title":"Ознаки ризику в інвестиційному офері","body":"Гарантія доходу, тиск через строк і компанія, яку неможливо перевірити, — причини призупинити оцінку запуску. Перевір юридичну особу, домен і дозволи через незалежні офіційні джерела. Попередження про ризики не виправляє оманливу основну обіцянку."},"RSK-07":{"title":"Адалт і дейтинг: межі категорії","body":"Визнач тип сервісу, зміст оголошення, кінцеву сторінку, аудиторію й формат показу. Навіть за однакової форми реєстрації правила для продуктів можуть відрізнятися. Якщо категорія неясна, залиш допуск непідтвердженим до перевірки першоджерел."},"RSK-08":{"title":"Чутливі дані й звіти","body":"Окремо перевір дозволеність вимірювання, передавання події й використання даних для аудиторій. Псевдонім або хеш не робить заборонену подію дозволеною. Для редакторських завдань використовуй агрегати або синтетичні рядки."},"SUB-01":{"title":"Від реєстрації до першої оплати","body":"У дейтингу узгодь, чи платять за прийняту реєстрацію (SOI), додаткове підтвердження (DOI) або покупку. Конкретну дію визначає договір. В інфобізнесі окремо рахуй реєстрацію на безплатний матеріал, пробний доступ і першу оплачену покупку. Для кожного етапу запиши свій знаменник."},"SUB-02":{"title":"Пробний період і ціна поновлення","body":"До згоди на пробний період покупець має бачити його тривалість, дату першого списання, суму, інтервал поновлення й спосіб скасування. Перевір узгодженість оголошення, сторінки й оплати. Для цифрових продуктів також чітко опиши, що входить у доступ і де шукати правила повернення коштів."},"SUB-03":{"title":"Вимірювання першого поновлення","body":"Із 50 перших платників у 40 вже настала дата першого поновлення. Із них 24 оплатили поновлення. Спостережуване поновлення — 60% серед тих, у кого настала дата. Для підсумкового порівняння врахуй однакове вікно повторної спроби оплати. Зберігай окремо добровільне скасування й неоплачене поновлення."},"SUB-04":{"title":"Скасування й повернення коштів","body":"Скасування майбутнього поновлення, повернення вже отриманого платежу й спір щодо платежу мають різні наслідки. Для часткового повернення враховуй суму. Окремо з’ясуй, чи змінюється право доступу та чи списується партнерська комісія. Звіряй фінансовий журнал із вивантаженням статусів."},"SUB-05":{"title":"Цінність підписника за когортою","body":"Дохід за перші 60 днів рахуй з урахуванням оплат і повернень тієї самої когорти. Для внеску відніми комісії та змінні витрати. Порівнюй когорти однакової зрілості. Прогноз повної LTV зазначай окремо від спостережуваного доходу за вибраний строк."},"SUB-06":{"title":"Приватність і класифікація дейтингу","body":"Перед дослідженням запуску уточни категорію продукту й перевір чинні правила платформи для цієї категорії, країни та формату. Дозвіл рекламувати продукт не визначає, які події й дані можна передавати до рекламної системи. Для навчання використовуй синтетичні ідентифікатори й агреговані дані."},"TOOL-01":{"title":"Keitaro — трекер на власному сервері","body":"Формує звіти за кліками й конверсіями, приймає статуси від партнерської мережі. Підходить, коли потрібен незалежний облік між системами і є відповідальний за сервер. Врахуй ліцензію, хостинг, оновлення й відновлення даних. Перевір обмеження тарифу за користувачами, доменами й API."},"TOOL-02":{"title":"Binom — власний або керований трекер","body":"Порівняй самостійну й керовану версії за витратами, лімітами, супроводом і доступом до даних. Керована версія зменшує потребу в адмініструванні, але обмеження за обсягом можуть різнитися. Перед покупкою звір тривалість тесту у формі замовлення: публічні сторінки описують різні варіанти."},"TOOL-03":{"title":"RedTrack — хмарна аналітика кампаній","body":"Кандидат, якщо потрібні міжплатформні інтеграції та звіти без власного сервера. На тесті перевір потрібні конверсії, чинні тарифні ліміти, доступ команди й експорт. Визнач, які дані вже є в кабінеті або CRM і що справді додасть трекер."},"TOOL-04":{"title":"Meta Ad Library — дослідження оголошень","body":"Використовуй для вивчення публічних оголошень, формулювань і форматів. Зафіксуй спостереження та сформулюй власну гіпотезу. Сам факт показу оголошення не підтверджує його ROI. Охоплення й глибина історії залежать від країни та категорії."},"TOOL-05":{"title":"Tilda — лендінг і форма","body":"Кандидат для швидкого прототипу сторінки. Для першого запуску перевір мобільний вигляд, надходження тестової заявки й підключення власного домену. Якщо потрібне перенесення на власний хостинг, перевір склад експорту та які функції після перенесення потребуватимуть окремої інтеграції."},"TOOL-06":{"title":"HubSpot CRM — статус заявки й угоди","body":"Використовуй CRM, коли заявки приймають кілька людей або результат відомий після контакту. Зафіксуй етапи, відповідального й причини відмов. На пробній вибірці перевір, чи CRM віддає потрібні поля для звірки. План вибирай за фактичною кількістю користувачів і контактів."},"TOOL-07":{"title":"Data Studio — звіт із кількох джерел","body":"Збери звіт про витрати й результати після звірки колонок, валюти, дати та ключів. Панель допомагає побачити зміни, але сама не виправляє пропуски й дублі. Перевір вартість конекторів, свіжість даних і права на перегляд звіту."},"TRK-01":{"title":"Ланцюжок подій","body":"Розклади шлях на клік, надсилання форми, прийняту заявку, рішення та виплату. Кожен етап має власний запис і власника даних. Рекламний кабінет показує атрибутовані події, журнал заявок — прийняття форми, партнерська мережа — статус оплати за договором."},"TRK-02":{"title":"Три ідентифікатори","body":"ID кліку пов’язує дію з переходом. ID заявки пов’язує статуси однієї заявки. ID події розрізняє окремі дії та може використовуватися для дедуплікації, якщо платформа її підтримує. Один клік може дати кілька допустимих транзакцій. У навчальних вивантаженнях використовуй вигадані ID."},"TRK-03":{"title":"Постбек і перевірка доставки","body":"Постбек — сповіщення однієї системи іншій про подію або зміну статусу. Якщо запису немає, знайди заявку у відправника, перевір наявність ID кліку, потім журнал надсилання, журнал приймання й підсумковий статус у звіті. Успішна відповідь на рівні транспорту сама по собі не показує, який статус потрапить у звіт."},"TRK-04":{"title":"Таблиця відповідності статусів","body":"Запиши, що означає кожний вхідний статус і до якої колонки він потрапляє. Приклад: заявка в роботі — pending, підтверджена — approved, скасована — rejected. У деяких оферах виплата залежить від доставки. Пов’язуй внутрішню позначку approved з нарахуванням після перевірки договору й налаштувань звіту."},"TRK-05":{"title":"Дублі, повторні покупки та зміна статусу","body":"Повтор сповіщення про ту саму покупку, нова покупка після того самого кліку й перехід pending → approved — три різні випадки. Перевір ключ події або транзакції й таблицю переходів статусу. Налаштування та версії трекера можуть по-різному обробляти повторні повідомлення."},"TRK-06":{"title":"Час кліку, події та звіту","body":"Клік у понеділок і заявка у вівторок можуть з’явитися в різних денних звітах. Зафіксуй часовий пояс, основу дати й час вивантаження. Для звірки із зовнішньою системою вибери колонку за часом події, якщо вона доступна й підходить для потрібної метрики. Повтори звірку після дозрівання даних."},"TRK-07":{"title":"Вимірювання й атрибуція","body":"Отримана подія й подія, зарахована рекламі, відповідають на різні запитання. Перед звіркою вибери одну метрику й перевір вікно, модель, набір дій і правила підрахунку. Різниця в підсумках сама по собі не доводить втрату даних. Шукай пропуски за рядками там, де обидві системи мають зіставний ID."},"TRK-08":{"title":"Два канали одного надсилання","body":"Браузер і сервер можуть повідомити про одне надсилання форми. У журналі перевір, чи збігається ідентифікатор цієї дії та звідки надійшли два повідомлення. Звір умови дедуплікації з документацією платформи. Спершу проведи один тест із відомим результатом і перевір, який запис прийнято та який зараховано."},"TRK-09":{"title":"Порядок звірки трьох систем","body":"Вибери когорту й подію, узгодь звіти за часом і статусом, потім порівняй рядки за ID. Для кожного пропуску запиши першу ділянку, де слід зникає, і факт, якого ще бракує. Створи малу контрольну вибірку прийнятих, відхилених заявок і тих, що очікують рішення."},"TRK-10":{"title":"Мінімальний журнал для розбору","body":"Для тестової звірки зазвичай достатньо часу з часовим поясом, вигаданого або дозволеного ID заявки, типу події, статусу, результату обробки й системи-відправника. Скриншоти з телефонами, адресами й токенами заміни знеособленими прикладами. Збережи умови фільтра й дату вивантаження поруч із результатом."},"VRT-01":{"title":"Товарка й послуги: різні воронки","body":"У товарці розрізняй заявку, підтвердження, доставку, оплату й повернення. У послугах розрізняй заявку, кваліфікацію, запис, візит і угоду. В обох моделях познач оплачуваний етап, кінцеву цінність для бізнесу й затримку між ними."},"VRT-02":{"title":"Післяплата й отримання","body":"За післяплати оформлення замовлення й отримання грошей розділені в часі. Позначай окремо замовлення в дорозі, скасування, неотримані товари й повернення. Звір, чи залежить винагорода від підтвердження, доставки або оплати. Визначення отриманого й оплаченого замовлення закріпи у звіті."},"VRT-03":{"title":"Економіка повернень","body":"У прикладі за 30 замовлень нарахували по $20. За 4 замовлення комісію скасували. Остаточний дохід — $520. За $360 рекламних та $90 інших змінних витрат внесок становить $70. Скасування віднось до початкової когорти, дату утримання — до руху коштів."},"VRT-04":{"title":"Кваліфікація заявки на послугу","body":"До закупівлі домовся, що робить заявку кваліфікованою: зона обслуговування, потрібна послуга, можливість зв’язатися й підтверджений інтерес. Відстежуй запис, явку й продаж як окремі етапи. Якщо критерії змінюються, збережи версію й дату зміни."},"VRT-05":{"title":"Завантаження й час відповіді","body":"Якщо заявок більше, а зустрічей менше, перевір час до першої відповіді, чергу, пропуски й наявність вільних слотів. Порівняй зіставні години й типи послуг. Падіння явки після збільшення обсягу може вказувати на обмеження обробки, але це треба перевірити даними."},"VRT-06":{"title":"Граничний CPL за ланцюжком","body":"Якщо 50% заявок проходять кваліфікацію, а 20% кваліфікованих доходять до продажу, продажем завершуються 10% усіх заявок. За внеску $150 на продаж до витрат на залучення очікуваний внесок — $15 на заявку. Якщо обробка коштує $3 на заявку, граничний рекламний CPL — $12. Частки мають відповідати послідовним етапам однієї когорти."},"VRT-07":{"title":"Причини відмови в товарці","body":"Попроси в мережі визначення кожного статусу. Кожна причина — гіпотеза про місце збою, яку перевіряють за даними:\n\n- **недозвон** — швидкість обробки і якість номера;\n- **відмова через ціну чи доставку** — розбіжність між оголошенням, сторінкою і дзвінком;\n- **дублі й помилкові номери** — форма і захист від повторної відправки.\n\nПорівнюй причини за когортами одного віку. Ранній апрув серед вирішених заявок може відрізнятися від зрілого в обидва боки."},"CASE-01":{"title":"CPL знизився, а підтверджень менше","body":"Дані синтетичні. За підтвердження платять $25. Інші змінні витрати — $2 на заявку. Кампанія A: $120 на рекламу, 20 заявок, 9 підтверджень, 11 відмов. Кампанія B: $120 на рекламу, 30 заявок, 6 підтверджень, 12 відмов, 12 очікують рішення. Вік останньої когорти B — 8 годин, A — 72 години. Залишок рекламного бюджету — $80.\n\n**Завдання.** Порівняй CPL і апрув від усіх заявок. Обчисли нижню й верхню межі апруву B та кількість додаткових підтверджень для беззбитковості. Назви два запити до джерел даних і вибери наступну дію.","solution":"**Розбір.** CPL A — $6, B — $4. Апрув A — 45%; діапазон B — 20–60%, якщо опрацьовані статуси остаточні. Враховані витрати B — $180, потрібно 8 підтверджень, тобто ще 2. Порівняй когорти однакового віку та запитай про причини відмов або час до першого контакту. Призупинити масштабування й визначити критерій перегляду рішення — обґрунтований вибір. Обмежений додатковий тест теж підходить, якщо є ліміт збитку й тест відповідає на конкретне запитання.\n\n**Критерії, 4 бали.** Правильний CPL, правильний діапазон, правильний поріг, обґрунтована дія із запитом даних — по балу."},"CASE-02":{"title":"Де зникли заявки?","body":"Дані синтетичні. Використай три вивантаження та примітку журналу з CASE-02.data.json. У тестовому журналі рекламних подій є зв’язок з ID заявки. У реальному кабінеті такого вивантаження може не бути.\n\n**Завдання.** Порахуй отримані й зараховані рекламні події, заявки партнерської мережі та рядки трекера. За ID поясни пропуски й розбіжність статусів. Скажи, з якої перевірки почнеш, перш ніж змінювати рекламу.","solution":"**Ключ.** Реклама отримала 6 повідомлень і зарахувала 5: e02 передано двома каналами, другий екземпляр дедупліковано. У партнерській мережі 5 заявок, у трекері 3. Для L03 постбек поточного статусу не надіслано, для L05 немає ID кліку. L04 є в обох системах, але для отриманого rejected не налаштовано відповідність, тому в знімку залишився pending. Перші перевірки — журнал надсилання L03, збереження ID для L05 і правило відповідності статусу для L04. Дані показують проблеми обліку. За ними не можна визначити причину якості трафіку.\n\n**Оцінка.** 1 бал за кількість і дедуплікацію, по балу за L03, L04 і L05, 1 бал за обґрунтований наступний крок. Усього 5."},"CASE-03":{"title":"Однаковий CTR, різний результат","body":"У кожній групі 10 000 показів, 200 кліків і $120 рекламних витрат. A: 40 заявок, 8 підтверджень. B: 30 заявок, 12 підтверджень. Когорти зрілі. Виплата $20 за підтвердження, інші змінні витрати $1 на заявку.\n\nЗавдання: обчисли CTR, CVR сторінки, рекламний CPL і внесок після вказаних витрат. Визнач, що перевірити перед масштабуванням.","solution":"Ключ: CTR 2% в обох, CVR 20% і 15%, CPL $3 і $4. Внесок A = $0, B = $90. Економіка B виглядає кращою. Для висновку про ефект перевір призначення варіантів, зрілість, розподіл аудиторій і невизначеність через малі числа. Оцінка: 1 бал за кожну з чотирьох метрик і 1 за перевірку перед рішенням."},"CASE-04":{"title":"Перенесення навички з товарки на послуги","body":"Дані синтетичні. В обох потоках 100 заявок і $500 реклами. У товарці підтвердили 40 замовлень, оплатили 25, за 3 оплатами комісію скасували. Виплата — $30 за оплачену й не скасовану подію. Інші змінні витрати $100. У послугах 50 заявок кваліфікували, 20 дійшли до візиту, 8 купили. Внесок до витрат на залучення $100 на продаж, обробка $200.\n\nЗавдання: порівняй CPL, оплачувану або кінцеву конверсію й внесок після витрат. Назви дві причини, чому для незрілої когорти висновок міг би змінитися.","solution":"Ключ: CPL $5 в обох. Товарка 22% і $60. Послуги 8% і $100. У товарці перевір затримку доставки й повернення, у послугах — час до візиту й угоди. Одна вибірка не доводить сталої різниці. По балу за CPL, обидва розрахунки й пояснення затримок. Усього 4."},"CASE-05":{"title":"Фіксована виплата чи частка","body":"Синтетичний приклад. Один і той самий потік дав 20 залікових дій. Модель A дає $30 за дію. Модель B дає $15 за дію плюс 25% від бази. Підтверджена база B: $800 за перший місяць і ще $600 сумарно за другий і третій. Витрати однакові.\n\nЗавдання: порівняй нарахування на 30-й і 90-й день, знайди базу, за якої B зрівняється з A, і назви, що ще потрібно перевірити для рішення щодо грошового потоку.","solution":"Ключ: A — $600, B — $500 і $650. База рівності $1 200. Додатково перевір фактичні строки виплати, скасування та відрахування. По балу за суми, поріг і перевірку грошового потоку. Усього 3."},"CASE-06":{"title":"Більше пробних періодів, менший внесок","body":"Дані синтетичні, обидві когорти дозріли за 60 днів. A: $200 рекламних витрат, 100 пробних періодів, 30 перших оплат і 12 поновлень. B: $200, 80 пробних періодів, 25 перших оплат і 18 поновлень. Кожен платіж $20. Повернення: $120 у A, $40 у B. Інші змінні витрати — $100 на групу.\n\nЗавдання: обчисли перехід від пробного періоду до оплати, частку першого поновлення серед перших платників і внесок за 60 днів. Назви перевірку перед перерозподілом бюджету.","solution":"Ключ: A — 30%, 40%, $420. B — 31,25%, 72%, $520. Перевір зіставність джерел, повноту повернень і вікно розрахунку. По балу за кожну з трьох метрик для обох груп і за обґрунтовану перевірку. Усього 4."},"CASE-07":{"title":"Обіцянка й економіка замовлення","body":"Дані синтетичні. Потік дав 50 заявок за $200 рекламних і $100 інших змінних витрат. 20 замовлень стали оплачуваними, 5 виплат згодом скасували. Виплата — $24. У креативі актор зображує рекомендацію продукту лікарем. Редактор отримав лише відгук покупця й дослідження іншої формули.\n\nЗавдання: обчисли внесок до та після скасувань. Поясни, що треба перевірити до публікації креативу. Назви два запити даних для з’ясування причин скасувань.","solution":"Ключ: $180 до скасувань, $60 після. Надані матеріали не підтверджують заявленого ефекту або справжньої рекомендації лікаря. Перевір заявлений ефект, докази для продукту, категорію та правила ринку й платформи. Запитай розподіл скасувань за причинами й зіставні дані за версіями оголошень та обробкою замовлень. По балу за кожен розрахунок, рішення щодо обіцянки й перевірку причин. Усього 4."},"CASE-08":{"title":"Депозити є, допуск ще не підтверджено","body":"Синтетичні дані: 100 реєстрацій, 12 перших депозитів, 8 залікових, одну виплату скасовано. Ставка $60 за остаточно зараховану дію. Враховані витрати $360. Документи підтверджують допуск оператора для ринку X, у брифі зазначено ринок Y. Погодження платформи для партнера й домену невідоме.\n\nЗавдання: обчисли дохід і внесок. Поясни різницю між депозитом і зарахуванням, назви перевірки перед рішенням про запуск.","solution":"Ключ: 7 оплачуваних дій, $420 доходу, $60 внеску. Для Y окремо перевір продукт, оператора, права партнера, платформу, вік і захист аудиторії. Позитивна економіка не підтверджує допуск. По балу за дохід, внесок, пояснення статусів і рішення щодо запуску. Усього 4."},"CASE-09":{"title":"Новий отримувач платежу","body":"Команда отримала рахунок за інструмент на $480. У договорі є попередній отримувач. У повідомленні просять переказати гроші на новий рахунок до кінця години й надіслати код входу для продовження послуги. Відомий контакт партнера є в попередньому листуванні.\n\nЗавдання: які факти перевіриш, що зафіксуєш і хто може підтвердити дію?","solution":"Ключ: відкласти платіж і передавання коду. Звірити рахунок і реквізити через відомий канал, передати питання відповідальному за витрати та зберегти повідомлення й підтвердження. Якщо доступ уже розкрито, запустити процедуру реагування. По балу за реакцію на код, незалежну звірку, фінансове погодження й збереження запису."},"CASE-10":{"title":"Не змінюй креатив навмання","body":"Дані вигадані. Група A дала 0 показів і $0 витрат, інтерфейс показує запуск завтра. Група B дала 2 000 показів, 50 вибраних кліків, 10 надсилань форми й 4 залікові замовлення за $60 витрат. Виплата $20 за замовлення, інші витрати $2 на форму.\n\nЗавдання: поясни, що робити з A. Для B обчисли CTR, рекламний CPL і внесок після витрат. Назви сигнал оптимізації та оплачуваний результат, якщо в налаштуваннях вибрано надсилання форми.","solution":"Ключ: для A спершу перевір розклад. CTR без показів невизначений. B: 2,5%, $6, $0 внеску. Сигнал — надсилання форми, оплачуваний результат — залікове замовлення. По балу за діагностику A, три розрахунки й розрізнення подій. Усього 5."},"CASE-11":{"title":"Кабінет показує 12 лідів, CRM — 10","body":"Синтетичні дані. За одну добу без затримки звіту CRM прийняла 10 заявок. Джерело подій отримало 12 сигналів: 8 заявок по одному разу, ще 2 надіслали й браузер, і сервер. Для цих двох заявок ID копій різняться. У звіті 12 зарахованих лідів, із 10 заявок у CRM 4 стали заліковими замовленнями. Витрати $60.\n\nЗавдання: обчисли CPL за кабінетом і CRM, ціну залікового замовлення. Назви гіпотезу й перевірку перед зміною бюджету.","solution":"Ключ: $5, $6, $15. Є дві пари подій із різними ID. На одній тестовій заявці перевір назву, ID, джерело й результат дедуплікації. До рішення про бюджет звір увесь вибраний період і модель звіту. По балу за кожен розрахунок і перевірку. Усього 4."},"CASE-12":{"title":"Дешевий сигнал, дороге замовлення","body":"Синтетичні дані. Група A запланована на завтра, витрати й покази дорівнюють нулю. Група B витратила $180. Кабінет зарахував 30 надсилань форми, CRM прийняла 24 заявки. Когорта зріла, 6 заявок стали оплачуваними замовленнями. Виплата $28 за замовлення, інші змінні витрати $2 за прийняту заявку.\n\nЗавдання: назви перевірку для A. Для B обчисли CPL за кожним джерелом, ціну оплачуваного замовлення й внесок. Запропонуй по одній гіпотезі для розбіжності лічильників і для збитку. Вибери наступну дію й критерій перегляду.","solution":"Ключ: A — перевірити розклад. B — $6, $7,50, $30, внесок −$60. Розбіжність можуть пояснити дублі, вікна або визначення заявки. Низьке зарахування може бути пов’язане з очікуваннями, обробкою або самим офером, потрібні дані. Не збільшувати бюджет до звірки сигналів і перевірки причин низького зарахування. По балу за A, CPL, ціну замовлення, внесок, дві обґрунтовані гіпотези та критерій рішення. Усього 6."},"VERT-TOV":{"title":"Товарка","body":"## Що просувають\n\nРеклама фізичних товарів. Партнер веде трафік і отримує виплату за визначену договором подію. Магазин сам отримує виручку й оплачує товар, логістику, виконання та повернення.\n\n## Хто платить і за що\n\nОфер → оголошення/лендинг → заявка → підтвердження → викуп. Для магазину відправлення і повернення змінюють фактичний внесок. У договорі партнера перевіряють, який статус створює виплату і чи може вона бути відкликана.\n\n## Бюджет і дані\n\n₴3 000 у брифі Vitok — задана межа навчального тесту. У моделі ₴180 × 40% − ₴6 допустимий CPL дорівнює ₴66. Розрахунковий ліміт на 30 прийнятих заявок — ₴1 980 за цією межею; це не оцінка достатності вибірки. Типовий тижневий бюджет Meta × Україна не встановлений.\n\n## Складність, стрес, ризик\n\n3/5 — звірити кабінет, CRM і оплачувану подію; 3/5 — статуси можуть дозрівати після витрат; 3/5 — витрати на рекламу, непідтверджені замовлення, логістика або скасування виплат. Оцінка редакторська, для описаного сценарію.\n\n## Білий, сірий і чорний приклади\n\nБілий: оголошення й лендинг чесно показують ціну та доставку. Сірий: договір не визначає правила дублів, тому економіку ще не можна підтвердити. Чорний: свідомо обіцяють безкоштовну доставку, якої немає."},"VERT-SRV":{"title":"Послуги","body":"## Що просувають\n\nЗалучення клієнтів місцевій компанії або B2B-команді. Баєр може працювати на власника бізнесу, агенцію або незалежно за прийняту заявку, запис чи угоду.\n\n## Хто платить і за що\n\nФорма → контакт → кваліфікація → запис → зустріч/замір → угода. Власник фінансує виконання послуги; партнерська оплата залежить від договору. Втрату до контакту й неявку рахують окремо.\n\n## Бюджет і дані\n\nУ LocaliQ Facebook Ads 2026 середній CPL категорії Home & Home Improvement — $42,95. 20 заявок за цим CPL математично коштували б $859; це похідний приклад, не спостережена кампанія й не український орієнтир. Синтетична вправа 017: ₴4 800 витрат / 40 заявок / 3 угоди.\n\n## Складність, стрес, ризик\n\n3/5 — воронка в CRM; 4/5 — час відповіді й неявки часто залежать від іншої команди; 3/5 — дешеві, але неякісні ліди або довгий цикл угоди. Оцінка редакторська, для описаного сценарію.\n\n## Білий, сірий і чорний приклади\n\nБілий: реальна послуга, прозорий критерій прийняття заявки. Сірий: провайдер і баєр по-різному визначають кваліфікацію. Чорний: вигадані звернення або свідомий продаж контактів із неправдивим поясненням їх походження."},"VERT-INF":{"title":"Інфобіз","body":"## Що просувають\n\nПросування курсів, консультацій, спільнот або підписок. Автор отримує виручку, партнер — фіксовану виплату або частку за договором.\n\n## Хто платить і за що\n\nКреатив → сторінка, вебінар або заявка → перша оплата → навчання → можливе повернення або поновлення. Перша оплата, продовження, скасування майбутнього списання та повернення грошей — різні події.\n\n## Бюджет і дані\n\nLocaliQ, категорія Education & Instruction: середній CPL $26,31 у Facebook Leads. 20 заявок за таким CPL = $526,20 як навчальний розрахунок. Це не ціна продажу курсу й не ринковий бюджет. Вправа 017: ₴6 000 реклами / 10 оплат / 2 повні повернення.\n\n## Складність, стрес, ризик\n\n3/5 — пов'язати рекламу, оплати й повернення; 3/5 — ризик переплутати ранню виручку зі зрілою; 4/5 — витрати на продукт, підтримку, повернення й репутацію. Оцінка редакторська, для описаного сценарію.\n\n## Білий, сірий і чорний приклади\n\nБілий: описує конкретний результат навчання й умови оплати. Сірий: відгуки є, а підстава для узагальненої обіцянки неясна. Чорний: фальшиві докази доходу або навмисно приховане продовження."},"VERT-NUT":{"title":"Нутра","body":"## Що просувають\n\nУ цій гілці нутра означає дієтичні добавки. Косметика та лікарські засоби потребують інших кейсів і окремої редакторської перевірки.\n\n## Хто платить і за що\n\nПрямий продаж або партнерська оплата за підтвердження чи викуп. Дохід від замовлення відокремлюють від витрат на рекламу, продукт, доставку, обробку й повернення. До кампанії перевіряють склад, категорію і рекламні твердження.\n\n## Бюджет і дані\n\nТиповий бюджет не встановлено. Умовна вправа: €25 виплати × 40% оплачуваних заявок − €2 змінних витрат = €8 граничного CPL. Для 30 заявок це €240 за межею беззбитковості, а не оцінка реального тесту. Для ринкового прикладу потрібен продукт, GEO, канал і досвід дозволеної кампанії.\n\n## Складність, стрес, ризик\n\n4/5 — економіка плюс доказовість заяв; 4/5 — повторні правки і залежність від статусів; 4/5 — відповідальність за твердження, відмови, повернення, обмеження в каналі. Оцінка редакторська, для описаного сценарію.\n\n## Білий, сірий і чорний приклади\n\nБілий: точне твердження, дозволене й підтверджене для обраного ринку. Сірий: у продавця є матеріали, але застосовність твердження до складу не встановлена. Чорний: фальшивий лікар або вигадана обіцянка лікування."},"VERT-DAT":{"title":"Дейтинг","body":"## Що просувають\n\nПросування сервісів знайомств. Звичайний сервіс знайомств, сексуально орієнтований сервіс і пропозиція платного супроводу потребують окремого розгляду за правилами каналу.\n\n## Хто платить і за що\n\nРеєстрація → підтвердження email → за потреби перевірка профілю → оплата. SOI/DOI описують одинарне або подвійне підтвердження згоди чи реєстрації за визначенням офера. Виплати за стартову й підтверджену подію можуть відрізнятися.\n\n## Бюджет і дані\n\nПідтвердженого діапазону не знайдено. Умовний розбір обліку: €300 витрат / 60 реєстрацій / 30 підтверджень / 6 оплат = €5, €10 та €50 за відповідну подію. Це одні й ті самі витрати, а не три різні бюджети.\n\n## Складність, стрес, ризик\n\n4/5 — розрізнити стадії, згоду й підписку; 4/5 — виплати залежать від якості та валідності; 4/5 — правила платформи, приватність, неповнолітні й шахрайство. Оцінка редакторська, для описаного сценарію.\n\n## Білий, сірий і чорний приклади\n\nБілий: реальний сервіс, прозорі умови й допуск перевірено. Сірий: сертифікація або категорія пропозиції ще невідома. Чорний: фальшиві профілі, приховані списання, обман щодо умов."},"VERT-GAM":{"title":"Гемблінг","body":"## Що просувають\n\nПромоція азартних ігор, букмекерства або інших окремих категорій. Спочатку встановлюють тип продукту, статус оператора, GEO, вік аудиторії та допустимість каналу.\n\n## Хто платить і за що\n\nОператор отримує дохід від гри. У партнерських угодах можуть зустрічатися CPA за кваліфіковану дію, частка доходу або гібрид. Реєстрація, перший депозит і оплачувана дія за договором можуть бути різними подіями. База частки й утримання визначаються договором.\n\n## Бюджет і дані\n\nРинковий бюджет не встановлено. Якщо GEO і канал не пройшли перевірку допуску, бюджет запуску в навчальному сценарії дорівнює €0. Для фінансового розбору можна дати історичні синтетичні дані та поміряти ціну підтвердженої, а не будь-якої події.\n\n## Складність, стрес, ризик\n\n5/5 — окремі правила ринку, платформи та договору; 5/5 — обмеження допусків і затримки перевірок; 5/5 — ризик порушень, невиплат і шкоди аудиторії. Оцінка редакторська, для описаного сценарію.\n\n## Білий, сірий і чорний приклади\n\nБілий: лише де підтверджено допуск оператора, каналу й аудиторії. Сірий: відсутнє підтвердження допуску. Чорний: промоція нелегального оператора, орієнтація на неповнолітніх або обіцянка швидкого збагачення."},"VERT-CRY":{"title":"Крипта","body":"## Що просувають\n\nМаркетинг продуктів і сервісів, пов'язаних із криптоактивами. Просвітницький контент, гаманець, біржа та інвестиційна пропозиція мають різні ризики й вимоги.\n\n## Хто платить і за що\n\nПідписка на інструмент, заявка на сервіс або партнерська виплата за прийняту дію. Реєстрація не дорівнює ідентифікації чи оплачуваній активації. Спочатку перевіряють юридичну особу, сервіс, юрисдикцію, заяви й дозвіл платформи.\n\n## Бюджет і дані\n\nТиповий бюджет не встановлено. Для перевірочного кейсу рекламний бюджет €0 до підтвердження контрагента і допустимості. В окремому прикладі розподіл витрат між етапами вимірюють за знеособленими даними дозволеної кампанії.\n\n## Складність, стрес, ризик\n\n5/5 — класифікація продукту, статус провайдера і перевірка умов; 4/5 — зміни умов і невизначені виплати; 5/5 — шахрайство, фінансова шкода та обмеження. Оцінка редакторська, для описаного сценарію.\n\n## Білий, сірий і чорний приклади\n\nБілий: прозорий продукт і підтверджена допустимість сценарію. Сірий: назва бренду відома, а статус саме цієї юридичної особи й послуги ще не звірений. Чорний: фальшивий сервіс, гарантований дохід або вимога передати секретну фразу гаманця."},"VERT-ADT":{"title":"Адалт","body":"## Що просувають\n\nУ цьому модулі окремо розглядаємо товари для дорослих і контент чи підписки для дорослих. Для кожної категорії свої правила каналу, вимоги до приватності та умови оплати.\n\n## Хто платить і за що\n\nТовар продається разово, сервіс може брати підписку, партнерська програма може оплачувати підтверджену дію. Окремо враховують повернення, оскарження списань, конфіденційність, згоду та вік. Початкове завдання — класифікувати офер і перевірити допуск.\n\n## Бюджет і дані\n\nЗіставних підтверджених витрат не знайдено. У вправі щодо допустимості витрати €0 до завершення перевірки. Бюджет для дозволеної категорії потребує окремих даних за GEO, каналом і типом продукту. Не об'єднувати різні категорії в одну цифру.\n\n## Складність, стрес, ризик\n\n5/5 — категорія, правила каналу, платіжні умови, приватність; 4/5 — відмови майданчиків і ризики списань; 5/5 — вік, згода, чутливі дані й потенційна шкода. Оцінка редакторська, для описаного сценарію.\n\n## Білий, сірий і чорний приклади\n\nБілий: дозволена категорія, дотримано вікових і платіжних умов та вимог до згоди. Сірий: класифікація лендинга або обсяг дозволу неясні. Чорний: матеріали без згоди або просування неповнолітнім."},"M22-01":{"title":"Перевірка офера до витрат","body":"1. Сформулюй під який продукт, ринок і джерело трафіку шукаєш офер.\n2. Запиши дослівно з договору, за яку подію платять. Заявка, кваліфікація, підтвердження та викуп можуть мати різні значення.\n3. Звір мінімальний поріг і графік виплат, холд, капу, вимоги до креативів, правила дублів і скасувань. Узгодь, як бачити причини відмови та подавати спір.\n4. Перевір контрагента і допустимість продукту та каналу. Фіксуй, які докази бачив і яка умова досі не підтверджена.\n5. Оціни ліміт витрат з урахуванням строку обробки заявок і того, коли кошти справді надійдуть. Перед тестом окремо узгодь контрольну заявку та спосіб виключити її з фінансових підсумків.\n\n**Шаблон рішення:** офер | GEO | канал | оплачувана подія | ставка і валюта | SLA обробки | холд і поріг | капа | дублікати/відмови | докази допуску | бюджетний ліміт | рішення."},"M22-02":{"title":"Перевірка вимірювання перед запуском","body":"1. Запиши очікувані кроки: клік → відкриття сторінки → відправка форми → запис у CRM → фінальний статус.\n2. Для кожного кроку зафіксуй, де він вимірюється і яким ідентифікатором зв’язується з наступним. Мітки кампанії й ідентифікатор конкретної події виконують різні функції.\n3. У тестовому режимі перевір один повний прохід. Звір чи збереглися мітки після переходів, чи запис з’явився в CRM і чи статус збігається з тим, що бачить трекер.\n4. Повтори одну тестову доставку події й перевір, що рахунок не збільшується вдруге. Окремо перевір відхилену заявку та тимчасову помилку передачі.\n5. Запиши в журнал дату, тестовий ID, очікуваний та фактичний результат. Познач контрольні записи, щоб не рахувати їх бізнес-результатом. Не клади контакти клієнтів або секрети в UTM чи загальнодоступні журнали.\n\n**Шаблон перевірки:** крок | ідентифікатор | очікуваний запис | перевірено в | тестовий статус | що виправити."},"M22-03":{"title":"Бриф креативу та перевірка воронки","body":"Почни з одного запитання, на яке має відповісти тест. Наприклад, чи пояснення вартості доставки до переходу на сайт змінює частку підтверджених заявок. Потім запиши, що залишається однаковим, що змінюємо і за якою бізнес-метрикою ухвалюємо рішення.\n\n**Бриф:** продукт і GEO | ситуація покупця | теза, яку можна підтвердити | формат і майданчик | дозволені матеріали | дія після перегляду | сторінка приземлення | змінна тесту | строк і критерій оцінки.\n\n**Перед публікацією:** зістав ціну, доставку, обіцянку й дію на оголошенні та сторінці. Відкрий шлях на телефоні. Пройди форму, включно з помилкою вводу, її поясненням і повідомленням про успішну відправку. Якщо тестуєш проміжну сторінку, запиши, яку інформацію вона додає, і оцінюй ефект до оплачуваної дії або зрілого статусу, а не тільки до кліку."},"SUP-01":{"title":"Чому апрув зник після збільшення обсягу","body":"Дві вигадані когорти одного офера. Перша: 40 прийнятих заявок віком 72 години, 12 підтверджень і 28 відмов. Друга: 80 прийнятих заявок віком 24 години, 0 підтверджень, 20 відмов і 60 у роботі. Витрати — ₴60 за прийняту заявку, виплата — ₴240 за підтвердження, інших витрат немає.\n\nПорахуй межу беззбитковості, апрув першої когорти й верхню межу можливого апруву другої. Обери наступний крок і дані, які треба запросити.","solution":"Межа беззбитковості: 60 ÷ 240 = 25%. Перша когорта: 12 ÷ 40 = 30%. У другій поточний підсумок 0%, але 60 заявок ще в роботі, тож верхня межа — (0 + 60) ÷ 80 = 75%. «У роботі» не означає відмову. Не додавай витрат понад погоджений ліміт і порівнюй когорти однакового віку. Запит: знеособлений ID, час прийняття і переходу, фінальний статус, код причини, виключені тестові записи, вік когорти, SLA обробки. Далі перевір потік у власній CRM, зміни джерел і креативів, правила відбору й навантаження на обробку. Відмінність статусів — підстава для розслідування, а не доказ шахрайства.","exercise":{"fields":[{"id":"be","type":"number","label":"Межа беззбитковості за апрувом","unit":"%","answer":25,"tolerance":0.5},{"id":"a1","type":"number","label":"Апрув першої когорти","unit":"%","answer":30,"tolerance":0.5},{"id":"max2","type":"number","label":"Верхня межа можливого апруву другої когорти","unit":"%","answer":75,"tolerance":0.5},{"id":"next","type":"choice","label":"Наступний крок","options":["Не додавати витрат понад погоджений ліміт і запросити порівняння когорт однакового віку","Зупинити офер: друга когорта має 0% апруву, отже партнер навмисно ріже заявки","Подвоїти бюджет: перша когорта вже вище межі беззбитковості","Зарахувати 60 заявок «у роботі» як відмови й закрити звіт"],"correct":0},{"id":"data","type":"multi","label":"Які дані запросити для перевірки","options":["Знеособлений ID заявки","Час прийняття і переходу статусу","Фінальний статус і код причини","Вік когорти й SLA обробки","Телефони клієнтів для самостійного обдзвону","Скриншот кабінету іншого партнера"],"correct":[0,1,2,3]}],"criteria":["Відрізняє «у роботі» від відмови","Правильно рахує межу беззбитковості","Просить дані, щоб перевірити принаймні два незалежні пояснення"]}},"SUP-02":{"title":"Дешеві заявки й дорогий результат","body":"Дві воронки монтажу обладнання, по ₴9 000 реклами. А: 90 заявок, 18 проведених замірів, 3 угоди. Б: 60 заявок, 18 замірів, 5 угод. Внесок з однієї угоди після виконання — ₴2 400.\n\nПорахуй ціну угоди й результат обох воронок. Визнач, за якою подією оцінювати, і що перевірити перед перенесенням бюджету.","solution":"А: CPL ₴100, угода ₴3 000, результат 3 × 2 400 − 9 000 = −₴1 800. Б: CPL ₴150, угода ₴1 800, результат 5 × 2 400 − 9 000 = +₴3 000. Дешевші заявки не означають дешевшого результату: оцінюй за угодою. Перш ніж переносити бюджет, перевір однаковий вік когорт, відмінності в обробці й зону обслуговування — без цього причинного висновку немає.","exercise":{"fields":[{"id":"cplA","type":"number","label":"CPL воронки А","unit":"₴","answer":100,"tolerance":0.5},{"id":"dealA","type":"number","label":"Ціна угоди А","unit":"₴","answer":3000,"tolerance":1},{"id":"dealB","type":"number","label":"Ціна угоди Б","unit":"₴","answer":1800,"tolerance":1},{"id":"resB","type":"number","label":"Результат Б після реклами","unit":"₴","answer":3000,"tolerance":1},{"id":"event","type":"choice","label":"За якою подією порівнювати воронки","options":["Угода (бізнес-подія)","Заявка: А дешевша","Проведений замір: їх однаково"],"correct":0},{"id":"check","type":"multi","label":"Що перевірити перед перенесенням бюджету","options":["Однаковий вік когорт","Можливі відмінності в обробці заявок","Зону обслуговування","Однакову кількість показів у кожній воронці","Скільки заявок дав найдешевший креатив"],"correct":[0,1,2]}],"criteria":["Називає оплачувану або бізнес-подію","Рахує її ціну","Пояснює, яких даних бракує для причинного висновку"]}},"SUP-03":{"title":"Яку подію бачить Meta і який результат потрібен бізнесу","body":"**Вправа.** Учень розкладає воронку на чотири колонки: подія, джерело правди, навіщо вона потрібна та коли вона дозріває. Наприклад, відправка форми може бути сигналом оптимізації, кваліфікація — статусом CRM, а оплата — бізнес-підсумком. На синтетичних даних перевіряє, що тестова заявка не потрапляє до бізнес-звіту, а повторна доставка події не робить одну заявку двома."},"SUP-04":{"title":"Де зламалася кампанія","body":"Розклади ціну зрілої події: CPA = CPM ÷ (1 000 × CTR × конверсія з кліку в зрілу подію), CTR і конверсія — частками.\n\n| Навчальний зріз | Покази | Витрати | Кліки | Прийняті заявки | Підтвердження |\n|---|---:|---:|---:|---:|---:|\n| А | 20 000 | ₴4 000 | 400 | 80 | 20 |\n| Б | 20 000 | ₴4 000 | 400 | 80 | 8 |\n\nПорахуй показники й обери, що можна сказати за цим зрізом.","solution":"CPM ₴200, CTR 2%, CPL ₴50 в обох зрізах. Ціна підтвердження зросла з ₴200 до ₴500, частка підтверджень знизилась з 25% до 10%. Верх воронки не змінився — розрив після заявки. Спочатку звір зрілість, умови обробки й причини відмов. Із цього зрізу не можна встановити, чи винен креатив, колцентр або склад трафіку: для гіпотези про креатив потрібні окремі зіставні дані, а не лише зростання частоти чи CPM.","exercise":{"fields":[{"id":"cpm","type":"number","label":"CPM (однаковий для А і Б)","unit":"₴","answer":200,"tolerance":0.5},{"id":"ctr","type":"number","label":"CTR","unit":"%","answer":2,"tolerance":0.05},{"id":"cpaB","type":"number","label":"Ціна підтвердження Б","unit":"₴","answer":500,"tolerance":1},{"id":"apprB","type":"number","label":"Частка підтверджень Б","unit":"%","answer":10,"tolerance":0.1},{"id":"concl","type":"choice","label":"Висновок за цим зрізом","options":["Змінилась лише частка підтверджень: звірити зрілість, обробку й причини відмов","Винен креатив: CPL однаковий, але він приводить гірших людей","Винен колцентр: частка підтверджень упала, отже змінити партнера","CPM зріс, тому ціна підтвердження зросла — знизити ставку й чекати"],"correct":0}],"criteria":["Правильно рахує CPM, CTR, ціну й частку підтверджень","Знаходить етап, де стався розрив","Не приписує причину без зіставних даних"]}},"SUP-05":{"title":"Загальний апрув виріс, а в кожному GEO впав","body":"Вигадані ринки А і Б, усі когорти дозріли. Кожна клітинка — підтвердження / прийняті заявки.\n\n| Період | Ринок А | Ринок Б |\n|---|---:|---:|\n| 1 | 40/100 | 8/100 |\n| 2 | 117/300 | 7/100 |\n\nПорахуй загальний апрув другого періоду, частку трафіку ринку А і апрув другого періоду з вагами першого.","solution":"Період 1: 48/200 = 24%. Період 2: 124/400 = 31%. Частка ринку А зросла з 50% до 75%, тому загальний апрув покращився, хоча кожен ринок упав на 1 п.п. З вагами першого періоду: 0,5 × 39% + 0,5 × 7% = 23%. Далі запитай витрати, виплати та інші витрати по кожному GEO, щоб оцінити фінансовий результат. Показники без однакових знаменників і віку когорт не порівнюй.","exercise":{"fields":[{"id":"tot2","type":"number","label":"Загальний апрув, період 2","unit":"%","answer":31,"tolerance":0.1},{"id":"shareA","type":"number","label":"Частка заявок ринку А, період 2","unit":"%","answer":75,"tolerance":0.1},{"id":"rew","type":"number","label":"Апрув періоду 2 з вагами періоду 1","unit":"%","answer":23,"tolerance":0.1},{"id":"why","type":"choice","label":"Чому загальний апрув виріс","options":["Зросла частка ринку А з вищим апрувом, хоча в кожному ринку апрув упав","Якість трафіку покращилась в обох ринках, тому загальний апрув виріс","Колцентр почав працювати краще й частіше додзвонюється клієнтам"],"correct":0}],"criteria":["Рахує загальний апрув і частку ринку","Перераховує з вагами першого періоду","Пояснює ефект зміни складу трафіку й просить фінансові дані по GEO"]}},"SUP-06":{"title":"Креатив отримав майже всі покази. Що це доводить?","body":"У вигаданій кампанії два креативи змінили тільки перші секунди відео. А отримав 10 000 показів і 20 цільових дій, Б — 1 000 показів і 3 дії. Покази розподіляла система доставки.\n\nПорахуй частоту дії на показ і реши, що можна стверджувати й як поставити наступний тест.","solution":"А: 20 ÷ 10 000 = 0,2%. Б: 3 ÷ 1 000 = 0,3%. У Б вища спостережена частота, але дій мало, а покази розподіляла система доставки — це пошук кандидата в поточній кампанії, а не контрольоване порівняння. Для наступного тесту зафіксуй одну змінну, спільну метрику й період, правило рішення, спосіб порівняння аудиторій і ліміт витрат. Керовані групи креативного тесту Meta документує окремо; доступність інтерфейсу перевіряють на конкретному акаунті.","exercise":{"fields":[{"id":"rA","type":"number","label":"Дій на показ, А","unit":"%","answer":0.2,"tolerance":0.01},{"id":"rB","type":"number","label":"Дій на показ, Б","unit":"%","answer":0.3,"tolerance":0.01},{"id":"concl","type":"choice","label":"Що доводить цей результат","options":["Нічого остаточного: дій мало, покази розподіляла система — це не контрольований тест","Б кращий: у нього вища частота дії, тож саме його варто масштабувати далі","А кращий: система віддала йому більше показів, отже він ефективніший"],"correct":0},{"id":"next","type":"multi","label":"Що зафіксувати для наступного тесту","options":["Одну змінну","Спільну метрику і період","Правило прийняття рішення","Спосіб порівняння аудиторій","Ліміт витрат","Змінити одночасно відео й текст, щоб пришвидшити тест","Зупинити тест, щойно один варіант вийде вперед"],"correct":[0,1,2,3,4]}],"criteria":["Рахує частоту дії на показ","Розрізняє пошук кандидата й контрольоване порівняння","Називає умови наступного тесту"]}},"EX17-SRV":{"title":"Послуги: угода в CRM","body":"Монтаж кондиціонерів. У CRM є заявка, контакт, кваліфікація, запис на замір, проведений замір і виграна або програна угода. Витрати на рекламу — ₴4 800: 40 заявок, 24 контакти, 12 записів, 8 проведених замірів і 3 угоди. Внесок після прямих витрат на виконання однієї угоди — ₴1 400.\n\nПорахуй CPL, ціну угоди й результат. Скільки угод потрібно для результату в плюсі? Як розібрати різницю між 40 заявками і 24 контактами?","solution":"CPL = 4 800 ÷ 40 = ₴120. Ціна угоди = 4 800 ÷ 3 = ₴1 600. Результат = 3 × 1 400 − 4 800 = −₴600; четверта угода дала б 5 600 − 4 800 = +₴800. На кожному етапі свій знаменник і свої заявки, що ще не дійшли до рішення. Різницю між 40 заявками й 24 контактами розклади на відкриті, дублікати, недоступні номери й відсутність спроби контакту: падіння між етапами саме не встановлює причину.","exercise":{"fields":[{"id":"cpl","type":"number","label":"CPL","unit":"₴","answer":120,"tolerance":0.5},{"id":"deal","type":"number","label":"Ціна виграної угоди","unit":"₴","answer":1600,"tolerance":1},{"id":"res","type":"number","label":"Результат після рекламних витрат","unit":"₴","answer":-600,"tolerance":1},{"id":"need","type":"number","label":"Мінімум угод для плюсу за інших рівних","unit":"","answer":4,"tolerance":0},{"id":"gap","type":"choice","label":"Різниця 40 заявок → 24 контакти","options":["Розкласти на відкриті, дублі, недоступні номери й заявки без спроби контакту","Це погані заявки з реклами: зменшити бюджет і змінити аудиторію","Колцентр не працює: змінити підрядника, бо 16 заявок втрачено без дзвінка"],"correct":0}],"criteria":["Рахує CPL, ціну угоди й результат","Визначає поріг угод","Розкладає втрати між етапами, не приписуючи причину"]}},"EX17-INF":{"title":"Інфобіз: перша оплата й повернення","body":"Вигаданий курс Excel для власників малого бізнесу, разова оплата ₴900. Витрати на рекламу — ₴6 000. Десять покупців оплатили, двом повернули повну суму.\n\nПорахуй оплати після повернень, ціну оплати й ціну покупця, який залишився. Обери чесне формулювання результату навчання.","solution":"Валові оплати 10 × 900 = ₴9 000, після двох повернень — ₴7 200; після реклами лишається ₴1 200 до комісій та інших витрат. Ціна оплати 6 000 ÷ 10 = ₴600, ціна покупця, який залишився, 6 000 ÷ 8 = ₴750. Повернення належить до платежу, тож першу оплату й повернення рахуй окремо. Непідтверджену обіцянку працевлаштування заміни конкретним результатом навчання.","exercise":{"fields":[{"id":"net","type":"number","label":"Оплати після повернень","unit":"₴","answer":7200,"tolerance":1},{"id":"cpp","type":"number","label":"Витрати на одну оплату","unit":"₴","answer":600,"tolerance":0.5},{"id":"cpk","type":"number","label":"Витрати на покупця, який залишився","unit":"₴","answer":750,"tolerance":0.5},{"id":"promise","type":"choice","label":"Як переписати обіцянку «гарантуємо працевлаштування»","options":["«Після курсу самостійно збереш звіт продажів зі зведенням і графіком»","«Після курсу гарантовано знайдеш роботу аналітиком у компанії»","«Заробіток від ₴30 000 на місяць уже за кілька тижнів після курсу»"],"correct":0}],"criteria":["Рахує оплати після повернень","Розрізняє ціну оплати й ціну покупця, що залишився","Замінює непідтверджену обіцянку конкретним результатом"]}},"FBK-020":{"title":"Як читати чужий звіт: Витрати, GEO й межі доказів","body":"Позначки: «самозвіт» означає опубліковану заяву автора, незалежного підтвердження не було. «Розраховано» означає арифметику за наведеними числами. Для довідника звичайних бюджетів потрібна серія зіставних запусків з одним GEO, каналом, типом кампанії, визначенням події та періодом.\n\n| ID | Що відомо | Що можна вивести | Що лишається відкритим |\n|---|---|---|---|\n| FBK-020-S02 | Рекрутинг, Meta, 5 місяців, $15 000 витрат, 3 848 заявок. Самозвіт 25.06.2026. | $3,90 за заявку після округлення. $3 000/місяць — арифметичне середнє за весь проєкт, а не спостережені щомісячні бюджети. | GEO не названий; число кампаній і розподіл витрат невідомі; фінальна ціна виходу на роботу не показана. |\n| FBK-020-S03 | Послуга, Meta, кілька GEO без розбивки; автор наводить $3 006 за один місяць і загальні витрати по ніші понад $15 000. Самозвіт 17.05.2026. | $3 006 можна зберегти як одиничне повідомлене місячне спостереження. | Немає зіставного розподілу по країнах, воронках та зрілих продажах. Не виводити прибуток або CPL для конкретного GEO. |\n| FBK-020-S04 | В огляді товарки наведено сторонній нутра-кейс: $609, 247 лідів, 64 підтвердження і окремо 34,22% апруву. | 609 ÷ 247 ≈ $2,47. Частка 64 ÷ 247 ≈ 25,9%. Це може бути інший знаменник, але його потрібно встановити. | Не використовувати 34,22% як частку всіх заявок. Не переносити цифри в бюджет товарки, не відомі повні витрати й поширеність такого результату. |\n\nЦя партія не додає підтвердженого типового бюджету по країні або Tier. Цифри корисні для вправи на якість джерела. У GEO-01 для кожного нового спостереження заповнювати окремо країну, період, тип суми, оплачувану подію та статус доказу."},"FBK-021":{"title":"Як читати чужий звіт: GEO, витрати й зрілі результати","body":"Мета — додати поодинокі спостереження до GEO-01. Самозвіти та редакційні перекази не встановлюють типовий бюджет. Всі суми в доларах США за публікацією. Посилання — у внутрішньому реєстрі.\n\n| ID | GEO, канал, період | Повідомлені дані | Розрахунок і обмеження |\n|---|---|---|---|\n| FBK-021-S01 | Австрія, Facebook, 14.12.2024–14.03.2025, нутра | $10 016 медіавитрат; 1 011 лідів, 440 підтверджень; $24 187 заявленого доходу | CPL ≈ $9,91; ціна підтвердження ≈ $22,76; апрув ≈ 43,52%. Різниця між заявленим доходом і медіавитратами — $14 171. Це не підтверджений чистий прибуток: немає звірки інших витрат, виплат і первинного звіту. |\n| FBK-021-S02 | GEO не названо, Facebook та Instagram, близько місяця, рекрутинг | $2 036,41; 415 заявок; 197 дійшли до співбесіди | CPL ≈ $4,91; співбесіда ≈ $10,34. Остаточна вартість виходу на роботу невідома. Запис не придатний для бюджету конкретної країни. |\n| FBK-021-S03 | GEO не названо, Facebook, тижневий зріз, e-commerce | Приблизно $4 900 витрат, близько $16 000 обороту, заявлений ROAS 3,37 | $16 000 ÷ $4 900 ≈ 3,27. Через округлення й можливу різницю періодів це питання для звірки, а не доказ помилки. Оборот і ROAS не замінюють дані про маржу та повернення. |\n| FBK-021-S04 | Польща, 24.04–14.05.2024, нутра; публікація від 24.02.2025 | Автор повідомив $1 126 прибутку й ROI 84% | Значення фактичних медіавитрат у доступному фрагменті не підтверджені. Не виводити spend з округленого ROI, поки невідомі склад витрат і знаменник. |\n\nЗіставного набору з кількох запусків на одному GEO з однаковим визначенням оплачуваної події цього разу немає. Австрія — одиничний історичний приклад, не норма Tier 1. Формат спостереження зберігає окремо дату публікації, період кампанії, тип джерела, стадію воронки та те, які витрати враховано."},"GDE-01":{"title":"Підвищення ставки","body":"Перед переговорами з партнером підготуй власний обсяг, частку підтверджених заявок і період спостереження. Попроси письмово визначити нову ставку, кап і дату набуття чинності."},"GDE-02":{"title":"Порівняння умов","body":"Зіставляй дохід на заявку, строки виплат і причини скасувань. Вища ставка може дати нижчий результат, якщо менше заявок оплачуються."},"GDE-03":{"title":"Коли створювати внутрішню команду","body":"Визнач, яку проблему має вирішити найм: швидкість тестів, якість вимірювання чи контроль витрат. До зарплат додай інструменти, час керівника й бюджет експериментів."},"GDE-04":{"title":"Карти доступу","body":"Розрізняй особистий профіль, рекламний акаунт, портфель, сторінку й джерело подій. У кожного активу зазнач власника, роль, відповідального за оплату та спосіб відновлення."},"GDE-06":{"title":"Рішення про бюджет після тесту","body":"Порівняй зрілі когорти, виплати, відхилення й витрати. Зафіксуй найближчу перевірку та умову зупинки."},"GDE-07":{"title":"Перед запуском лендінгу","body":"На телефоні перевір видимість ціни й умов, кнопку, помилки форми та підтвердження подання. Проведи тестову заявку з дозволеними даними й звір її запис у CRM."},"GDE-08":{"title":"Швидкість і результат","body":"Лабораторний тест допомагає знайти вузьке місце. Польові дані описують фактичний досвід. Якщо польових даних бракує, перевір сторінку на телефоні й повтори тест після однієї зміни."},"GDE-09":{"title":"Журнал гіпотез","body":"Запиши, що змінилося, з якою версією порівнювали й за якої умови повернешся до тесту. Зберігай також невизначені результати. Фінансова звірка має посилатися на той самий запуск."},"GDE-10":{"title":"Частка витрат і причина збитку","body":"Визнач внесок кожного запуску після витрат і частку спільних витрат, яку можна йому обґрунтовано віднести. Спершу перевір базу порівняння й зрілість статусів."},"GDE-11":{"title":"Повернення в товарці","body":"Розділи статус доставки, оплату й скасування комісії. Для підсумку зістав замовлення з нарахуванням. Внесок і рух грошей оновлюй за їхніми окремими датами."},"INS-02":{"title":"Граничний CPL","body":"Виплата × частка оплачуваних заявок − інші змінні витрати на заявку. Знаменник обирається явно; відсоток і частка розрізняються. Відʼємний поріг означає, що інші витрати вже перевищують очікуваний дохід.\n\n**Де порахувати:** «База» → Інструменти → Калькулятори → «Гранична вартість ліда»."},"INS-03":{"title":"ROI та чистий внесок","body":"ROI = (дохід − враховані витрати) ÷ враховані витрати. Для нульових витрат ROI не визначений. Показує валюту, повернення й склад витрат.\n\n**Де порахувати:** «База» → Інструменти → Калькулятори → «Беззбитковість і ROI»."},"INS-07":{"title":"Чекліст лендінгу","body":"Версія сторінки, мобільний вигляд, ціна й доставка, обовʼязкові поля, успішна й неуспішна відправка, CRM, подія. На виході видно неперевірені пункти. Секрети й дані клієнта не потрібні.\n\n**Як користуватись:** це чекліст для самоперевірки перед запуском. Рішення й перевірку записуй у шаблонах M22-01 і M22-02 «Бази»; окремого інструмента немає."},"INS-08":{"title":"Журнал експериментів","body":"Бриф, ID варіанта, зміна, бюджет, дні спостереження, умови зупинки й висновок. Зрілість результату показано явно.\n\n**Як користуватись:** це шаблон журналу. Цифри запусків веди в «Мої цифри» (Профіль), рішення — у шаблоні M22-01; окремого інструмента немає."},"CASE-13":{"title":"Чому форма погіршилась?","body":"**Навчальні дані.** До зміни форми — 200 відвідувань, 20 заявок прийняла CRM, 8 зараховано. Після зміни — 200 відвідувань, 30 подій у браузері, 15 заявок прийняла CRM, 6 зараховано. У кожному періоді витрати $100. Версії сторінки змінились. Виплата $20 за зараховану заявку, інші змінні витрати $1 за прийняту заявку.\n\n**Завдання.** Знайди, де виникла розбіжність. Обчисли CPL за даними CRM і внесок в обох періодах. Назви контрольний тест перед зміною реклами.","solution":"**Ключ.** CPL за CRM $5 → $6,67. Внесок $40 → $5. Зістав версію сторінки, подію й відповідь CRM для успішної та відхиленої тестових заявок. Частка зарахованих серед прийнятих однакова, 40%, а розбіжність виникла до обліку в CRM.\n\nПовʼязані картки: EXP-03, TRK-08, TRK-09, VRT-03."}};
export default data;
